/* @lc app=leetcode id=2507 lang=kotlin */ class Solution { fun smallestValue(n: Int): Int = generateSequence(n) { x -> (2..x).fold(0 to x) { (s, t), d -> if (d * d > t) s to t else generateSequence(s to t) { (s2, t2) -> if (t2 % d == 0) s2 + d to t2 / d else null }.last() }.let { if (it.second > 1) it.first + it.second else it.first } }.zipWithNext().first { it.first <= it.second }.first }